// UI language. Japanese is the default and lives in the HTML itself; other languages replace
// text marked with data-i18n (textContent), data-i18n-html, data-i18n-ph (placeholder) and
// data-i18n-title (title + aria-label). Their strings live in js/lang/<path>.js and only the
// current language's file is loaded.
// The language comes from the URL (/ko/ or ?lang=ko), then a saved choice, then the browser's
// language settings. Each language also has its own page (/en/, /ko/…) with translated meta
// tags and preview image, generated by tools/build-pages.mjs.

export const LANGS = [
  { id: 'ja', label: '日本語', path: '/', ddragon: 'ja_JP', cdragon: 'ja_jp' },
  { id: 'en', label: 'English', path: '/en/', ddragon: 'en_US', cdragon: 'default' },
  { id: 'ko', label: '한국어', path: '/ko/', ddragon: 'ko_KR', cdragon: 'ko_kr' },
  { id: 'zh-CN', label: '简体中文', path: '/zh-cn/', ddragon: 'zh_CN', cdragon: 'zh_cn' },
  { id: 'zh-TW', label: '繁體中文', path: '/zh-tw/', ddragon: 'zh_TW', cdragon: 'zh_tw' },
  { id: 'th', label: 'ไทย', path: '/th/', ddragon: 'th_TH', cdragon: 'th_th' },
  { id: 'vi', label: 'Tiếng Việt', path: '/vi/', ddragon: 'vi_VN', cdragon: 'vi_vn' },
  { id: 'es', label: 'Español', path: '/es/', ddragon: 'es_MX', cdragon: 'es_mx' },
  { id: 'pt-BR', label: 'Português', path: '/pt-br/', ddragon: 'pt_BR', cdragon: 'pt_br' },
  { id: 'de', label: 'Deutsch', path: '/de/', ddragon: 'de_DE', cdragon: 'de_de' },
  { id: 'fr', label: 'Français', path: '/fr/', ddragon: 'fr_FR', cdragon: 'fr_fr' },
];

const LANG_KEY = 'riftcard:lang';

function fromTag(tag) {
  const t = String(tag || '').toLowerCase();
  if (t.startsWith('ja')) return 'ja';
  if (t.startsWith('ko')) return 'ko';
  if (/^zh-(tw|hk|mo)|^zh-hant/.test(t)) return 'zh-TW';
  if (t.startsWith('zh')) return 'zh-CN';
  if (t.startsWith('pt')) return 'pt-BR';
  for (const id of ['th', 'vi', 'es', 'de', 'fr']) if (t.startsWith(id)) return id;
  if (t) return 'en';
  return '';
}

function detect() {
  const byPath = LANGS.find((l) => l.path !== '/' && location.pathname.startsWith(l.path));
  if (byPath) return byPath.id;
  const param = new URLSearchParams(location.search).get('lang');
  if (LANGS.some((l) => l.id === param)) return param;
  try {
    const saved = localStorage.getItem(LANG_KEY);
    if (LANGS.some((l) => l.id === saved)) return saved;
  } catch { /* storage unavailable */ }
  // Search engines index the Japanese page.
  if (/bot|crawl|spider|slurp|lighthouse/i.test(navigator.userAgent)) return 'ja';
  for (const tag of navigator.languages || [navigator.language]) {
    const id = fromTag(tag);
    if (id) return id;
  }
  return 'ja';
}

export const LANG = detect();
export const LANG_INFO = LANGS.find((l) => l.id === LANG);

export function setLang(id) {
  try {
    localStorage.setItem(LANG_KEY, id);
  } catch { /* storage unavailable */ }
  const url = new URL(location.href);
  url.searchParams.delete('lang');
  url.pathname = LANGS.find((l) => l.id === id).path;
  location.replace(url);
}

